{
  "findings": [
    {
      "ref": "[D524]",
      "area": "age_gating",
      "claim": "A parent reports that Discord requires users to be at least 13 years old but does not verify age beyond a birth date entry.",
      "stance": "risk",
      "quote": "users must be at least 13 years old— in line with U.S. privacy laws (COPPA). But there's no real age verification beyond entering a birth date, so younger kids can easily sign up if they lie about their age"
    },
    {
      "ref": "[D524]",
      "area": "age_gating",
      "claim": "A parent reports that age-based safety features are only applied when the birth date is entered correctly, and can be bypassed with a fake date.",
      "stance": "risk",
      "quote": "These tools can help, but they work best when you and your teen set them up together and talk through why certain settings matter. Still, it's important to know that Discord isn't designed specifically for teens. There's no separate \"kids mode,\" and 13-year-olds are basically using the same version of the app as adults—just with a few safety settings that can be changed."
    },
    {
      "ref": "[D524]",
      "area": "contact",
      "claim": "A parent reports that strangers can message teens directly unless friend request settings are limited to \"Friends of Friends\".",
      "stance": "risk",
      "quote": "Friend request settings: Lets teens limit who can send them friend requests: *Everyone*, *Friends of Friends*, or *Server Members*. Choosing *Friends of Friends* can reduce unwanted contact. Note that teens can switch this back to *Everyone*. If they're in a public server, they may still receive requests from strangers inside that space."
    },
    {
      "ref": "[D524]",
      "area": "contact",
      "claim": "A parent reports that direct messages from strangers are blocked by default for teen accounts, but can be disabled.",
      "stance": "mitigation",
      "quote": "Teen Safety Assist Features: Aimed at teen accounts, these features are turned on by default for under-18 accounts: *Safety alerts appear when you receive a message from a new contact.*"
    },
    {
      "ref": "[D524]",
      "area": "money",
      "claim": "A parent reports that Discord does not sell games but integrates with platforms like Steam and Xbox, which can pressure teens to spend money to access premium spaces.",
      "stance": "risk",
      "quote": "are highly visible and can create pressure for teens to spend in order to access premium spaces or content tied to their interests."
    },
    {
      "ref": "[D524]",
      "area": "money",
      "claim": "A parent reports that Discord does not have loot boxes or pay-to-win mechanics, but in-app purchases are possible through linked platforms.",
      "stance": "neutral",
      "quote": "Discord doesn't sell games anymore, but it integrates with platforms like Steam and Xbox. When teens see what their friends are playing, they may feel pressure to buy games or in-game items to join in."
    },
    {
      "ref": "[D524]",
      "area": "data",
      "claim": "A parent reports that Discord collects user data and may share it for ads, but the policy is not fully detailed in the excerpt.",
      "stance": "risk",
      "quote": "Discord has added more safety tools in recent years, but they still don't offer the same level of control or protection you'll find on platforms designed for younger users. Many settings are optional, easy to change, and rely on your teen using them responsibly."
    },
    {
      "ref": "[D524]",
      "area": "content",
      "claim": "A parent reports that teens may encounter NSFW or age-restricted content on Discord, especially in public servers.",
      "stance": "risk",
      "quote": "Discord hosts thousands of communities for virtually any interest imaginable. While many servers provide positive spaces for connection, teens may come across harmful or inappropriate content ranging from mild to serious, including sexual images, violent or graphic content, discussions of drugs and alcohol, hate speech, or manipulative ideologies."
    },
    {
      "ref": "[D524]",
      "area": "content",
      "claim": "A parent reports that the platform may expose teens to manipulative or extreme messaging in some communities.",
      "stance": "risk",
      "quote": "Some communities may share manipulative or extreme messaging, like content that promotes hate, reinforces gender stereotypes, or frames relationships and power in unhealthy ways."
    },
    {
      "ref": "[D524]",
      "area": "developer_record",
      "claim": "A parent reports that there is no mention of fines, breaches, lawsuits, or regulatory actions against Discord's developer in the provided text.",
      "stance": "neutral",
      "quote": "The provided text does not mention any regulatory actions, fines, or legal issues involving Discord's developer."
    }
  ]
}
